<?phpadd_action('admin_menu', 'wooen_register_menu');add_action('admin_menu', 'wooen_register_menu_shop');function wooen_register_menu(): void{    add_menu_page(        'Theme Settings',        'Theme Settings',        'manage_options',        'setting_shop',        'setting_shop_layout',        'dashicons-sos',        25    );    add_submenu_page(        'setting_shop',        'General Settings',        'General Settings',        'manage_options',        'setting_shop_tab_one',        'setting_shop_layout'    );    add_submenu_page(        'setting_shop',        'Slider Management',        'Slider Management',        'manage_options',        'setting_shop_tab_two',        'setting_shop_layout'    );    add_submenu_page(        'setting_shop',        'Banner Management',        'Banner Management',        'manage_options',        'setting_shop_tab_three',        'setting_shop_layout'    );    add_submenu_page(        'setting_shop',        'Contact Us',        'Contact Us',        'manage_options',        'setting_shop_tab_four',        'setting_shop_layout'    );    add_submenu_page(        'setting_shop',        'Social Media Management',        'Social Media Management',        'manage_options',        'setting_shop_tab_five',        'setting_shop_layout'    );    add_submenu_page(        'setting_shop',        'Frequently Asked Questions (FAQ)',        'Frequently Asked Questions (FAQ)',        'manage_options',        'setting_shop_tab_six',        'setting_shop_layout'    );    add_submenu_page(        'setting_shop',        'Newsletter Management',        'Newsletter Management',        'manage_options',        'setting_shop_tab_seven',        'setting_shop_layout'    );    $general_settings = get_option('_wooen_settings_set_general', []);    $sms_setting = isset($general_settings['register_from_sms_enable'])        ? $general_settings['register_from_sms_enable']        : 'no';    if ($sms_setting === 'yes') {    add_submenu_page(        'setting_shop',        'SMS Settings',        'SMS Settings',        'manage_options',        'setting_shop_tab_eight',        'setting_shop_layout'    );    }    // SMS Settings - Only available when enabled    add_submenu_page(        'edit.php',        'Wishlist',        'Wishlist',        'manage_options',        'wishlist_setting',        'shw_wishlist_setting_list_layout',        ''    );}function wooen_register_menu_shop(): void{    add_menu_page(        'Shop Settings',        'Shop Settings',        'manage_options',        'setting_shop2',        'setting_shop_layout2',        'dashicons-cart',        30    );}function setting_shop_layout(){    if (!current_user_can('manage_options')) {        wp_die('Unauthorized access!');    }    $page = isset($_GET['page'])        ? $_GET['page']        : 'setting_shop_tab_one';    $tab = str_replace('setting_shop_', '', $page);    // Retrieve settings again for the SMS tab    $general_settings = get_option('_shw_settings_set_general', []);    $sms_setting = isset($general_settings['register_from_sms_enable'])        ? $general_settings['register_from_sms_enable']        : 'no';    ?>    <div class="wrap">        <h1 class="nav-tab-wrapper">            <a href="?page=setting_shop_tab_one"               class="nav-tab <?php echo $tab === 'tab_one' ? 'nav-tab-active' : ''; ?>">                General Settings            </a>            <a href="?page=setting_shop_tab_two"               class="nav-tab <?php echo $tab === 'tab_two' ? 'nav-tab-active' : ''; ?>">                Slider Settings            </a>            <a href="?page=setting_shop_tab_three"               class="nav-tab <?php echo $tab === 'tab_three' ? 'nav-tab-active' : ''; ?>">                Banner Management            </a>            <a href="?page=setting_shop_tab_four"               class="nav-tab <?php echo $tab === 'tab_four' ? 'nav-tab-active' : ''; ?>">                Contact Us            </a>            <a href="?page=setting_shop_tab_five"               class="nav-tab <?php echo $tab === 'tab_five' ? 'nav-tab-active' : ''; ?>">                Social Media            </a>            <a href="?page=setting_shop_tab_six"               class="nav-tab <?php echo $tab === 'tab_six' ? 'nav-tab-active' : ''; ?>">                Frequently Asked Questions (FAQ)            </a>            <a href="?page=setting_shop_tab_seven"               class="nav-tab <?php echo $tab === 'tab_eight' ? 'nav-tab-active' : ''; ?>">                Newsletter Management            </a>            <?php if ($sms_setting === 'yes') { ?>                <a href="?page=setting_shop_tab_eight"                   class="nav-tab <?php echo $tab === 'tab_seven' ? 'nav-tab-active' : ''; ?>">                    SMS Settings                </a>            <?php } ?>        </h1>        <div class="tab-content" style="margin-top: 20px;">            <?php            switch ($tab) {                case 'tab_one':                    tnm_general_setting_html_layout();                    break;                case 'tab_two':                    tnm_setting_slider_html_layout();                    break;                case 'tab_three':                    tnm_banner_setting_html_layout();                    break;                case 'tab_four':                    tnm_contact_us_setting_layout();                    break;                case 'tab_five':                    tnm_social_media_html_layout();                    break;                case 'tab_six':                    tnm_faq_html_layout();                    break;                case 'tab_seven':                    tnm_setting_newsltter_layout();                    break;                case 'tab_eight':                    tnm_setting_sms_layout();                    break;                default:                    shw_info_setup_theme();            }            ?>        </div>    </div>    <?php}// =========================================================// Layout Loader Functions// =========================================================function tnm_general_setting_html_layout(){    require_once WOOEN_PLUGIN_DIR . 'view/admin/general-setting-html-layout.php';}function tnm_banner_setting_html_layout(){    require_once WOOEN_PLUGIN_DIR . 'view/admin/banner-setting-html-layout.php';}function tnm_contact_us_setting_layout(){    require_once WOOEN_PLUGIN_DIR . 'view/admin/contact-us-setting-layout.php';}function tnm_social_media_html_layout(){    require_once WOOEN_PLUGIN_DIR . 'view/admin/social-media-html-layout.php';}function tnm_faq_html_layout(){    require_once WOOEN_PLUGIN_DIR . 'view/admin/faq-setting-html-layout.php';}function tnm_setting_sms_layout(){    require_once WOOEN_PLUGIN_DIR . 'view/admin/sms-setting-layout.php';}function tnm_setting_newsltter_layout(){    require_once WOOEN_PLUGIN_DIR . 'view/admin/newsletter-setting-layout.php';}function tnm_setting_slider_html_layout(){    require_once WOOEN_PLUGIN_DIR . 'view/admin/slider-setting-html-layout.php';}function shw_info_setup_theme(): void{    require_once WOOEN_PLUGIN_DIR . 'view/admin/info-setup-theme.php';}